namespace ghidra.app.cmd.disassemble;

using ghidra.framework.cmd;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.util.task;

/**
 * Command for setting the fallthrough property on an instruction.
 */
public class SetFlowOverrideCmd : BackgroundCommand<Program> {
	Address instAddr;
	AddressSetView set;
	FlowOverride flowOverride;

	/**
	 * Constructs a new command for overriding the flow  semantics of an instruction.
	 * @param instAddr the address of the instruction whose flow override is
	 * to be set.
	 * @param flowOverride the type of flow override.
	 */
	public SetFlowOverrideCmd(Address instAddr, FlowOverride flowOverride) : this(null, instAddr, flowOverride)
    {
	}

	/**
	 * Constructs a new command for overriding the flow  semantics of all instructions
	 * within the address set.
	 * @param set the address set of the instructions whose flow override is
	 * to be set.
	 * @param flowOverride the type of flow override.
	 */
	public SetFlowOverrideCmd(AddressSetView set, FlowOverride flowOverride) : this(set, null, flowOverride)
    {
	}

	private SetFlowOverrideCmd(AddressSetView set, Address instAddr, FlowOverride flowOverride) : base("Set Flow Override", true, true, true)
    {
		this.instAddr = instAddr;
		this.set = set;
		this.flowOverride = flowOverride;
	}

	/* @Override */
	public bool applyTo(Program program, TaskMonitor monitor) {

		if (set != null) {
			int cnt = 0;
			// simplified monitor to avoid too much overhead
			// assumes one instruction per range
			monitor.initialize(set.getNumAddressRanges());
			foreach (Instruction instr in program.getListing().getInstructions(set, true)) {
				if (monitor.isCancelled()) {
					break;
				}
				instr.setFlowOverride(flowOverride);
				monitor.setProgress(++cnt);
			}
			return true;
		}

		Instruction instr = program.getListing().getInstructionAt(instAddr);
		if (instr == null) {
			return false;
		}

		if (instr.getFlowOverride() == flowOverride) {
			return true;
		}

		instr.setFlowOverride(flowOverride);

		return true;
	}

}
